public class Main {
    static String summary(java.util.List<String> xs) {
        long total = xs.stream().count();
        long nonEmpty = xs.stream().filter(s -> !s.isEmpty()).count();
        return total + ":" + nonEmpty;
    }
    public static void main(String[] args) {
        System.out.println(summary(java.util.List.of("a", "", "b")));
    }
}
